    "explanation": "To rotate left by d: reverse(0, d-1), reverse(d, n-1), then reverse(0, n-1).",
    "syntax": "def reverse(l, r): ...\nreverse(0, d-1); reverse(d, n-1); reverse(0, n-1)",
