    "codeExample": "# Program for Merge Sort\ndef merge_sort(arr):\n    if len(arr) > 1:\n        mid = len(arr) // 2\n        L = arr[:mid]\n        R = arr[mid:]\n\n        merge_sort(L)\n        merge_sort(R)\n\n        i = j = k = 0\n        # Merge sorted halves\n        while i < len(L) and j < len(R):\n            if L[i] <= R[j]:\n                arr[k] = L[i]\n                i += 1\n            else:\n                arr[k] = R[j]\n                j += 1\n            k += 1\n\n        while i < len(L):\n            arr[k] = L[i]; i += 1; k += 1\n        while j < len(R):\n            arr[k] = R[j]; j += 1; k += 1\n    return arr\n\nnumbers = [38, 27, 43, 3, 9, 82, 10]\nprint(f\"Original: {numbers}\")\nmerge_sort(numbers)\nprint(f\"Sorted  : {numbers}\")\n",
