    "codeExample": "# Program for Iterative Bottom-Up Merge Sort\ndef merge(arr, l, m, r):\n    n1 = m - l + 1\n    n2 = r - m\n    L = arr[l : m + 1]\n    R = arr[m + 1 : r + 1]\n    \n    i = j = 0\n    k = l\n    while i < n1 and j < n2:\n        if L[i] <= R[j]:\n            arr[k] = L[i]; i += 1\n        else:\n            arr[k] = R[j]; j += 1\n        k += 1\n    while i < n1:\n        arr[k] = L[i]; i += 1; k += 1\n    while j < n2:\n        arr[k] = R[j]; j += 1; k += 1\n\ndef iterative_merge_sort(arr):\n    n = len(arr)\n    curr_size = 1\n    while curr_size < n:\n        left = 0\n        while left < n - 1:\n            mid = min(left + curr_size - 1, n - 1)\n            right = min(left + 2 * curr_size - 1, n - 1)\n            merge(arr, left, mid, right)\n            left += 2 * curr_size\n        curr_size *= 2\n\nnumbers = [12, 11, 13, 5, 6, 7]\nprint(f\"Original: {numbers}\")\niterative_merge_sort(numbers)\nprint(f\"Sorted  : {numbers}\")\n",
