    "codeExample": "# Program for ShellSort\ndef shell_sort(arr):\n    n = len(arr)\n    gap = n // 2\n    \n    while gap > 0:\n        for i in range(gap, n):\n            temp = arr[i]\n            j = i\n            while j >= gap and arr[j - gap] > temp:\n                arr[j] = arr[j - gap]\n                j -= gap\n            arr[j] = temp\n        gap //= 2\n    return arr\n\nnumbers = [12, 34, 54, 2, 3]\nprint(f\"Original: {numbers}\")\nshell_sort(numbers)\nprint(f\"Sorted  : {numbers}\")\n",
