    "codeExample": "# Program for Radix Sort (LSD)\ndef counting_sort_digit(arr, exp):\n    n = len(arr)\n    output = [0] * n\n    count = [0] * 10\n\n    for i in range(n):\n        index = (arr[i] // exp) % 10\n        count[index] += 1\n\n    for i in range(1, 10):\n        count[i] += count[i - 1]\n\n    for i in range(n - 1, -1, -1):\n        index = (arr[i] // exp) % 10\n        output[count[index] - 1] = arr[i]\n        count[index] -= 1\n\n    for i in range(n):\n        arr[i] = output[i]\n\ndef radix_sort(arr):\n    max_val = max(arr)\n    exp = 1\n    while max_val // exp > 0:\n        counting_sort_digit(arr, exp)\n        exp *= 10\n    return arr\n\nnumbers = [170, 45, 75, 90, 802, 24, 2, 66]\nprint(f\"Original: {numbers}\")\nradix_sort(numbers)\nprint(f\"Sorted  : {numbers}\")\n",
