    "codeExample": "# Program for Comb Sort\ndef comb_sort(arr):\n    n = len(arr)\n    gap = n\n    shrink = 1.3\n    sorted_flag = False\n\n    while not sorted_flag:\n        gap = int(gap / shrink)\n        if gap <= 1:\n            gap = 1\n            sorted_flag = True\n\n        for i in range(0, n - gap):\n            if arr[i] > arr[i + gap]:\n                arr[i], arr[i + gap] = arr[i + gap], arr[i]\n                sorted_flag = False\n    return arr\n\nnumbers = [8, 4, 1, 56, 3, -44, 23, -6, 28, 0]\nprint(f\"Original: {numbers}\")\ncomb_sort(numbers)\nprint(f\"Sorted  : {numbers}\")\n",
