    "codeExample": "# Program for Cocktail Shaker Sort\ndef cocktail_sort(arr):\n    n = len(arr)\n    swapped = True\n    start = 0\n    end = n - 1\n\n    while swapped:\n        swapped = False\n        # Forward pass: left to right\n        for i in range(start, end):\n            if arr[i] > arr[i + 1]:\n                arr[i], arr[i + 1] = arr[i + 1], arr[i]\n                swapped = True\n        if not swapped:\n            break\n        swapped = False\n        end -= 1\n        # Backward pass: right to left\n        for i in range(end - 1, start - 1, -1):\n            if arr[i] > arr[i + 1]:\n                arr[i], arr[i + 1] = arr[i + 1], arr[i]\n                swapped = True\n        start += 1\n    return arr\n\ndata = [5, 1, 4, 2, 8, 0, 2]\nprint(f\"Original: {data}\")\ncocktail_sort(data)\nprint(f\"Sorted  : {data}\")\n",
